"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Сервер Model Context Protocol даёт агенту для кода дополнительные инструменты: файлы, интернет, браузер, GitHub и тому подобное. Он доступен только агентам, которые входят через собственный инструмент командной строки в Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode): агент, работающий только по API-ключу, использовать его здесь не может.",
