"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Агенты действуют шагами четырёх видов: выполнить команду, прочитать файл, записать файл или изменить часть файла. Прежде чем выполнится команда или изменится файл, вы видите, что именно произойдёт, и выбираете «Выполнить» (или «Применить»), «Пропустить» или «Всегда разрешать в этом чате». Для чтения файлов в текущей папке подтверждение не нужно.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Агенты могут ошибаться. Читайте, что они хотят выполнить, особенно в оболочке «Режим работы» или с Root, где команда может удалить приложения или изменить настройки.",
