"Android builds the whole palette from the color below.": "Android создаёт всю палитру из цвета ниже.",
"Android can't verify this APK's signature (edited after signing, or unsigned).": "Android не может проверить подпись этого APK (изменён после подписания или не подписан).",
"Android can't verify this APK's signature (edited after signing, or unsigned). It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Android не может проверить подпись этого APK (изменён после подписания или не подписан). Сначала он устанавливается как есть; если Android его отклонит, устанавливается копия, подписанная ключом этого приложения.",
"Android is clearing the caches. This can take up to a minute or two; you can keep using the app.": "Android очищает кэши. Это может занять до двух минут, а приложением можно продолжать пользоваться.",
"Android keeps its settings behind the shell. Connect one of them in Working Modes, then come back.": "Android хранит свои настройки за оболочкой. Подключите один из режимов в разделе «Режимы работы» и вернитесь.",
"Android lists this overlay as unavailable": "Android считает этот оверлей недоступным",
"Android lists this overlay as unavailable (its target app is missing, or it is not approved), so it cannot be switched.": "Android считает этот оверлей недоступным (целевое приложение отсутствует или оверлей не одобрен), поэтому его нельзя переключить.",
"Android only uses a setting that something reads by that name. Leave the value empty to create it with nothing in it.": "Android использует только ту настройку, которую что-то читает по этому имени. Оставьте значение пустым, чтобы создать настройку без значения.",
"Android repaints in a moment, and apps may restart.": "Через мгновение Android перерисует интерфейс, а приложения могут перезапуститься.",
"Android reports no signing certificate for this app.": "Android не сообщает сертификат подписи для этого приложения.",
"Android version": "Версия Android",
"Android versions": "Версии Android",
"Android will not ask again. Allow it by hand: App info of this app, Permissions, Additional permissions, Run commands in Termux environment.": "Android больше не спросит. Разрешите вручную в настройках этого приложения: «Разрешения» → «Дополнительные разрешения» → «Run commands in Termux environment».",
"Android will use your wallpaper’s colors with the Tonal Spot style again.": "Android снова будет использовать цвета ваших обоев со стилем Tonal Spot.",
"Android’s hidden settings": "Скрытые настройки Android",
"Animator duration scale (1 = normal, 0 = off)": "Масштаб длительности анимации (1 = обычная, 0 = выкл.)",
"Another archive job is still running": "Другая операция с архивом ещё выполняется",
"Another batch action is already running": "Другое групповое действие уже выполняется",
"Another folder": "Другая папка",
"Another theme": "Другая тема",
"Anthropic does not allow other apps to sign in with a Claude Pro or Max account. Claude Code, Anthropic's own tool, can: it runs in Termux, and the Terminal chats through it. With an API key saved, Claude Code uses the key instead.": "Anthropic не разрешает другим приложениям выполнять вход с аккаунтом Claude Pro или Max. Claude Code, собственный инструмент Anthropic, это может: он работает в Termux, а Терминал общается через него. Если сохранён API-ключ, Claude Code использует его вместо аккаунта.",
"Any screen density": "Любая плотность экрана",
"Anyone who has the password can open it. If it is lost, the files can not be recovered.": "Любой, кто знает пароль, может открыть архив. Если пароль потерян, восстановить файлы не удастся.",
"AnythingLLM": "AnythingLLM",
"AnythingLLM runs on a computer or a server (Desktop or Docker). Enter its address (like http://192.168.1.20:3001/api/v1/openai) and an API key from AnythingLLM, Settings, Developer API. Each workspace shows up as a model.": "AnythingLLM работает на компьютере или сервере (Desktop или Docker). Введите его адрес (например, http://192.168.1.20:3001/api/v1/openai) и API-ключ из AnythingLLM (Настройки → Developer API). Каждое рабочее пространство отображается как модель.",
