"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Тема и оверлеи меняются через оболочку. Подключите один из режимов в разделе «Режимы работы» и вернитесь.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Тема и оверлеи меняются через оболочку. Подключите один из режимов в разделе «Режимы работы» и вернитесь. Используемые сейчас цвета показаны и без подключения.",
"Changing this can break setup, apps or the system. Only change it if you know what it does.": "Изменение этого параметра может нарушить настройку, приложения или систему. Меняйте его, только если знаете, что он делает.",
