"Choose something to send first": "Сначала выберите, что отправить",
"Choose the ones to send to the device": "Выберите, что отправить на устройство",
"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Способ входа выбирается на панели подключения агента. Инструменты без сборки для Android устанавливаются в окружение Debian внутри Termux. Это занимает несколько минут и примерно до 1 GB места; провайдеры официально не поддерживают Android, поэтому инструмент может работать не на каждом телефоне.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Выберите, что делает дополнительная кнопка в каждой строке списка приложений. Это всегда значок, а те кнопки, что зависят от приложения («Включить / Отключить», «Установить / Удалить», «Возобновить / Приостановить»), меняют значок и действие в соответствии с текущим состоянием приложения.",
"Choosing files works in the app": "Выбор файлов работает в приложении",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Вход с подпиской Claude Pro или Max и вход через аккаунт Google разрешены только в собственных приложениях провайдеров: Anthropic и Google не позволяют другим приложениям использовать такой вход. Поэтому Терминал выполняет вход через официальные инструменты командной строки в Termux, где открывается страница входа на сайте самого провайдера:",
