"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind — это MCP-сервер: инструмент, который даёт ИИ-агентам управление Android-устройством через ADB (приложения, файлы, журналы, снимки экрана). Сам по себе это не чат.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind установлен в Debian. Запустите его командой: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Добавьте его своему агенту как MCP-сервер (адрес выводится при запуске).",
