"EXPERT": "ЭКСПЕРТ",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Каждый агент хранит это в своём файле, так же как и данные своего официального входа, поэтому один и тот же сервер можно подключить нескольким агентам и пользоваться им с любым из них. Codex хранит токен удалённого сервера в переменной окружения, а не в своём файле. Не проверялось для каждой версии каждого инструмента.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "У каждой оболочки свой экран, и она остаётся открытой, пока вы работаете на других вкладках: cd, export и переменные сохраняются от команды к команде. «Перезапустить оболочку» запускает новую.",
"Earlier certificates (the signing key was changed)": "Прежние сертификаты (ключ подписи был изменён)",
