"Installing Ollama": "Установка Ollama",
"Installing from File Manager runs through ADB, Wireless Debugging, Shizuku or Root, and none of them is connected right now.": "Установка из файлового менеджера выполняется через ADB, отладку по Wi-Fi, Shizuku или Root, но сейчас ни один из них не подключён.",
"Installing…": "Установка…",
"Installs Ollama in Termux, starts it and downloads a small coding model (qwen2.5-coder 1.5B, about 1 GB). This takes a few minutes.": "Устанавливает Ollama в Termux, запускает его и скачивает небольшую модель для кода (qwen2.5-coder 1.5B, около 1 GB). Это займёт несколько минут.",
"Installs from File Manager need ADB, Wireless Debugging or Shizuku": "Для установки из файлового менеджера нужны ADB, отладка по Wi-Fi или Shizuku",
"Installs the backed-up APK over the installed one, then re-applies its permissions and app ops.": "Устанавливает APK из резервной копии поверх установленного, затем заново применяет его разрешения и App Ops.",
"Interface": "Интерфейс",
"Interfaces": "Интерфейсы",
"Internal storage": "Внутренняя память",
"Internal storage ›": "Внутренняя память ›",
"Issuer": "Издатель",
"It could not be saved": "Не удалось сохранить",
"It did not finish": "Не завершено",
"It did not work": "Не получилось",
"It finishes installing itself the first time it opens.": "При первом запуске он сам завершает установку.",
"It goes back to the version that came with the phone. An older version often cannot use the data of a newer one, so it may lose its data.": "Приложение вернётся к версии, поставлявшейся с телефоном. Старая версия часто не может использовать данные более новой, поэтому данные могут быть потеряны.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "У него нет сборки для Android, поэтому он устанавливается в контейнер Debian внутри Termux (несколько минут, несколько сотен MB). Уже выполненные шаги быстро пропускаются.",
"It is not set any more": "Больше не задано",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Оно удаляется для пользователя устройства. Системное приложение можно вернуть кнопкой «Переустановить».",
"It is removed for you. A system app stays on the phone and can be brought back with Reinstall.": "Оно удаляется для вас. Системное приложение остаётся на телефоне, и его можно вернуть кнопкой «Переустановить».",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Сначала он устанавливается как есть; если Android его отклонит, устанавливается копия, подписанная ключом этого приложения.",
"Its settings, accounts and files on the device are deleted.": "Его настройки, аккаунты и файлы на устройстве будут удалены.",
"Its settings, accounts, saved games and the files in its own storage are deleted. This cannot be undone.": "Его настройки, аккаунты, сохранённые игры и файлы в его собственном хранилище будут удалены. Это нельзя отменить.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Страница IzzyOnDroid",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan бесплатно запускает ИИ-модели на вашем компьютере. На компьютере: Jan → Настройки → Local API Server: укажите хост 0.0.0.0 и запустите сервер, затем введите здесь адрес компьютера (например, http://192.168.1.20:1337/v1). Версии Jan для Android нет.",
"Jan.ai": "Jan.ai",
"Keep": "Оставить",
