"Keyboard": "Клавиатура",
"Keys and servers": "Ключи и серверы",
"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Ключи шифруются ключом, который хранится в защищённом оборудовании телефона, и отправляются только на адрес своего провайдера. После ввода страница их больше не видит; показываются только последние четыре символа.",
"Keys, default agent and model, shells, and what agents may do without asking": "Ключи, агент и модель по умолчанию, оболочки и то, что агентам разрешено без запроса",
