"Kilo Code is an open-source AI coding agent built as an editor extension (VS Code, JetBrains), not a phone terminal tool, so it does not chat here.": "Kilo Code — ИИ-агент для кода с открытым исходным кодом, созданный как расширение редактора (VS Code, JetBrains), а не инструмент для терминала телефона, поэтому общаться с ним здесь нельзя.",
