"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon — персональный ассистент с открытым исходным кодом (навыки, голос), который работает на компьютере с Node.js и Python. У него нет версии для Android, и это не агент для кода, поэтому в этом Терминале он не общается.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Разрешить Termux принимать команды от других приложений",
"Let them act without asking": "Разрешить действовать без запроса",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Позволяет агенту читать и записывать файлы в папке, указанной в конце команды (замените /sdcard по желанию).",
"Lets the agent think in explicit steps before it acts.": "Позволяет агенту рассуждать по шагам, прежде чем действовать.",
"Lets this app change a few protected system settings used by some advanced features.": "Позволяет этому приложению менять несколько защищённых системных настроек, которые нужны некоторым расширенным функциям.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Позволяет этому приложению устанавливать выбранные вами файлы пакетов, например APK, APKS и XAPK из вашего хранилища.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Позволяет этому приложению открывать экран другого приложения из фонового режима, например только что установленного.",
