"Levels and package data come from the UAD-NG project (GPL-3.0). The list is downloaded from their GitHub and cached on this phone.": "Уровни и данные о пакетах взяты из проекта UAD-NG (GPL-3.0). Список скачивается с их GitHub и кешируется на этом телефоне.",
