"Looks on this Wi-Fi network for devices that offer wireless debugging. A device that waits for a pairing code shows up with Pair, one that is already paired shows up with Connect.": "Ищет в этой сети Wi-Fi устройства с включённой отладкой по Wi-Fi. Устройство, ожидающее код подключения, показывается с кнопкой «Сопрячь», уже сопряжённое — с кнопкой «Подключить».",
