"Termux Cheat Sheet": "Шпаргалка по Termux",
"Termux answered": "Termux ответил",
"Termux answered. All set.": "Termux ответил. Всё готово.",
"Termux could not be opened. Is it installed?": "Не удалось открыть Termux. Он установлен?",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termux пока не принимает команды от других приложений. В Termux выполните:",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termux пока не принимает команды от других приложений: выполните в Termux команду из шага 3 и проверьте снова.",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termux бесплатен. Скачайте его из F-Droid или GitHub; старая сборка из Google Play не подходит.",
"Termux is not installed. It is free from F-Droid or GitHub.": "Termux не установлен. Он бесплатен: скачайте его из F-Droid или GitHub.",
"Termux is not set up for this app yet.": "Termux ещё не настроен для этого приложения.",
"Termux permission": "Разрешение Termux",
"Termux setup": "Настройка Termux",
"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Оболочки Termux сначала читают ~/.bash_profile или ~/.profile (PATH и т. п.). Выключите, если ваш профиль запускает другую программу.",
