"The lists are cut at 3000 entries each.": "Каждый список обрезан до 3000 записей.",
"The manifest does not ask for any extra library (no uses-library entry).": "Манифест не запрашивает дополнительных библиотек (записей uses-library нет).",
"The older storage permission some apps still check for.": "Старое разрешение на хранилище, которое всё ещё проверяют некоторые приложения.",
"The pairing code has 6 digits": "Код подключения состоит из 6 цифр",
"The password is used only for this archive, only while it is open. It is never saved.": "Пароль используется только для этого архива и только пока он открыт. Он никогда не сохраняется.",
"The phone may still apply it. It is looked at again in a moment.": "Телефон всё же может применить это. Через мгновение значение будет проверено снова.",
"The phone may still apply it. The list is read again in a moment.": "Телефон всё же может применить это. Через мгновение список будет прочитан снова.",
"The project gives no description for this package.": "У проекта нет описания для этого пакета.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Провайдеры официально не поддерживают Android: инструмент может работать не на каждом телефоне. При сбое Терминал показывает точные сообщения инструмента.",
