"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Затем дайте этому приложению разрешение «Run commands in Termux environment» и проверьте подключение. «Настройка Termux» в настройках Терминала проведёт вас по всем шагам.",
"There is no undo.": "Отменить это нельзя.",
"These apps are currently selected for this action:": "Для этого действия выбраны следующие приложения:",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Релизы этих приложений размещены на сайтах, которые это приложение не может проверить напрямую. Их может отслеживать Obtainium.",
"These files are too different to compare line by line. View each one instead.": "Эти файлы слишком различаются для построчного сравнения. Просмотрите каждый отдельно.",
"Third-party packages only": "Только сторонние пакеты",
"This App's ADB Key": "ADB-ключ этого приложения",
"This Shizuku version is too old. Please update Shizuku.": "Эта версия Shizuku слишком старая. Обновите Shizuku.",
"This action cannot be undone.": "Это действие нельзя отменить.",
"This action needs access to files on this phone.": "Для этого действия нужен доступ к файлам на этом телефоне.",
"This agent": "Этот агент",
