"Turn Wi-Fi off": "Выключить Wi-Fi",
"Turn Wi-Fi on": "Включить Wi-Fi",
"Turn a tab off to take it out of the tab bar and use the arrows to put the tabs in the order you like. Application Manager and About always stay where they are.": "Отключите вкладку, чтобы убрать её с панели вкладок, а стрелками расставьте вкладки в нужном порядке. «Менеджер приложений» и «О программе» всегда остаются на своих местах.",
"Turn mobile data off": "Выключить мобильные данные",
"Turn mobile data on": "Включить мобильные данные",
