"Type a command for the device and press Run. A line that starts with \"adb \" goes to adb itself (adb pull, adb forward ...).": "Введите команду для устройства и нажмите «Выполнить». Строка, начинающаяся с «adb », передаётся самому adb (adb pull, adb forward ...).",
"Type a command for the device and press Run. Start a line with \"adb \" to send it to adb itself (adb pull, adb forward ...). The $ button switches to adb for every line.": "Введите команду для устройства и нажмите «Выполнить». Начните строку с «adb », чтобы передать её самому adb (adb pull, adb forward ...). Кнопка $ переключает на adb для каждой строки.",
"Type a whole number, like 280": "Введите целое число, например 280",
"Type in the search box to find a word anywhere in the guide. This guide is in English.": "Введите слово в поле поиска, чтобы найти его в любом месте руководства. Руководство написано на английском языке.",
